<!DOCTYPE html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><title><?= htmlspecialchars($SITE_TITLE ?? 'MartPoint',ENT_QUOTES,'UTF-8'); ?> — Tax Rates</title><link rel="stylesheet" href="<?= htmlspecialchars($theme_link,ENT_QUOTES,'UTF-8'); ?>css/font-awesome-4.7.0/css/font-awesome.min.css"><style>*{box-sizing:border-box}body{margin:0;background:#f2f6f3;color:#173128;font-family:Inter,-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif}.screen{max-width:620px;min-height:100vh;margin:auto;padding:14px 14px 125px}.head{display:flex;align-items:center;gap:12px;margin-bottom:10px}.head a{font-size:19px;color:#176534}.titles{flex:1}.store-name{font-size:11px;color:#64748b;font-weight:700;text-transform:uppercase}.head h1{font-size:19px;margin:2px 0}.avatar{width:34px;height:34px;border-radius:50%;background:#dcf5e5;color:#166534;display:grid;place-items:center;font-weight:800}.status{display:flex;justify-content:space-between;font-size:11px;color:#64748b;margin-bottom:14px}.card{background:#fff;border:1px solid #e1e9e5;border-radius:14px;padding:17px;margin-bottom:14px}.card h2{font-size:16px;margin:0 0 12px}.tax-row{display:flex;justify-content:space-between;padding:11px 0;border-bottom:1px solid #e8eee9}.tax-row:last-child{border:0}.tax-row small{color:#64748b}.field{margin-bottom:13px}.field label{display:block;font-size:12px;font-weight:700;margin-bottom:6px}.field input{width:100%;border:1px solid #d8e2db;border-radius:9px;padding:11px;font-size:16px}.save{background:#166534;color:#fff;border:0;border-radius:9px;padding:12px 18px;font-weight:800}.flash{padding:10px;border-radius:9px;margin-bottom:12px;background:#e9f8ed;color:#14532d}</style></head><body><div class="screen"><header class="head"><a href="<?= base_url('mobile/oil_processing'); ?>" aria-label="Back"><i class="fa fa-chevron-left"></i></a><div class="titles"><div class="store-name"><?= htmlspecialchars($SITE_TITLE ?? 'MartPoint',ENT_QUOTES,'UTF-8'); ?></div><h1>Tax Rates</h1></div><div class="avatar"><?= htmlspecialchars(strtoupper(mb_substr((string)($this->session->userdata('display_name') ?: 'U'),0,1)),ENT_QUOTES,'UTF-8'); ?></div></header><div class="status"><span><i class="fa fa-clock-o"></i> <span id="plant-tax-clock"></span></span><span id="plant-tax-sync">Online</span></div>
<?php foreach(array('success','error') as $kind): if($this->session->flashdata($kind)): ?><div class="flash"><?= htmlspecialchars($this->session->flashdata($kind),ENT_QUOTES,'UTF-8'); ?></div><?php endif; endforeach; ?>
<div class="card"><h2>Available rates</h2><?php if(!$tax_rates): ?><p style="color:#64748b;margin:0">No tax rates yet. Add one only when your business needs it.</p><?php endif; ?><?php foreach($tax_rates as $tax): ?><div class="tax-row"><span><?= htmlspecialchars($tax->tax_name,ENT_QUOTES,'UTF-8'); ?> <small><?= $tax->status ? 'Active' : 'Inactive'; ?></small></span><strong><?= htmlspecialchars($tax->tax,ENT_QUOTES,'UTF-8'); ?>%</strong></div><?php endforeach; ?></div>
<?php if(permissions('tax_add')): ?><form class="card" action="<?= base_url('oil_processing/save_tax_rate'); ?>" method="post"><h2>Add a tax rate</h2><input type="hidden" name="<?= htmlspecialchars($this->security->get_csrf_token_name(),ENT_QUOTES,'UTF-8'); ?>" value="<?= htmlspecialchars($this->security->get_csrf_hash(),ENT_QUOTES,'UTF-8'); ?>"><div class="field"><label for="tax-name">Tax name</label><input id="tax-name" name="tax_name" maxlength="100" required placeholder="e.g. VAT"></div><div class="field"><label for="tax-rate">Percentage</label><input id="tax-rate" name="tax" type="number" min="0" max="100" step="0.01" required placeholder="Enter rate"></div><button class="save" type="submit">Save tax rate</button></form><?php endif; ?></div>
<?php $this->load->view('mobile/bottom_nav',array('active'=>'more')); ?><?php $this->load->view('mobile/chat'); ?><script>(function(){var c=document.getElementById('plant-tax-clock'),s=document.getElementById('plant-tax-sync');function tick(){c.textContent=new Date().toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'});s.textContent=navigator.onLine?'Online':'Offline';}tick();setInterval(tick,30000);window.addEventListener('online',tick);window.addEventListener('offline',tick);})();</script></body></html>
